function checkThreeDaysNotRunning() {
  const table = "Team_TECH_BPA.script_tracker";
  const schema = "Team_TECH_BPA";
  let slackChannel = "automation-errors";

  const connection = Database.getReadOnlySQLConnection(schema);
  const inactiveScriptResults = Database.bulkRead(connection,`SELECT
          name,
          function_name,
          last_run,
          last_success,
          message
        FROM ${table}
        WHERE last_run < DATE_SUB(NOW(), INTERVAL 3 DAY)
      `,
      [
        "name",
        "function_name",
        "last_run",
        "last_success",
        "message"
      ]);

  const threeDaysNotRunning = new Map()
  let count = 0;
  for ( const inactiveScript of inactiveScriptResults) {
    count++

    const functionName = `${inactiveScript.name}.${inactiveScript.function_name}
    `
    Logger.log(`❌ Three Days Not Running: ${functionName}`)

    let scriptsMap = threeDaysNotRunning.get(slackChannel)
    if (!scriptsMap) {
      scriptsMap = new Map()
      threeDaysNotRunning.set(slackChannel, scriptsMap)
    }
    scriptsMap.set(functionName, inactiveScript.message)
  }

  let notificationCount = 0
  for (const [slackChannel, scriptsMap] of threeDaysNotRunning) {
    if ( slackChannel === "automation-errors") {
      try {
        if ( Test.isTest() ) {
          Logger.log(`Post to ${slackChannel}: ❌ There are ${scriptsMap.size} mysql scripts that have not run for 3 or more days. Please look into these and either mark the column is_active as TRUE(if needed) or leave is_active as FALSE/delete the script if necessary:\n${Array.from(scriptsMap.keys()).join("\n")}`)
        } else {
//          Slack.postMessageToChannel(slackChannel, `❌ There are ${scriptsMap.size} mysql scripts that have not been run for 3 or more days. Please look into these and either mark the column is_active as TRUE(if needed) or leave is_active as FALSE/delete the script if necessary`, Array.from(scriptsMap.keys()).join("\n"))
        }
        notificationCount += 1
      } catch (e) {
        Logger.log(`❌ Error sending report to slack channel ${slackChannel}: ${e.message}`)
      }
    } else {
      Logger.log(`❌ Found ${scriptsMap.size} mySQL scripts without a slack channel to send to: ${Array.from(scriptsMap.keys()).join(", ")}`)
    }
    Utilities.sleep(1100)
  }

  if (notificationCount > 0) {
  Logger.log(`Sent ${notificationCount} notifications to ${slackChannel}`);
  }
}

